import {
  InsufficientStockError,
  InvalidOrderTransitionError,
  InvalidValueError,
} from '../../domain/errors/DomainError';
import { ConflictError, NotFoundError, ValidationError } from './ApplicationError';

export type ErrorKind = 'validation' | 'not_found' | 'conflict' | 'internal';

/** A transport-neutral description of a failed operation. */
export interface ClassifiedError {
  readonly kind: ErrorKind;
  readonly code: string;
  readonly message: string;
  readonly details?: unknown;
}

export function classifyError(error: unknown): ClassifiedError {
  if (error instanceof ValidationError || error instanceof InvalidValueError) {
    return { kind: 'validation', code: 'INVALID_INPUT', message: error.message };
  }
  if (error instanceof NotFoundError) {
    return { kind: 'not_found', code: 'NOT_FOUND', message: error.message };
  }
  if (error instanceof InsufficientStockError) {
    return {
      kind: 'conflict',
      code: 'INSUFFICIENT_STOCK',
      message: error.message,
      details: error.shortages,
    };
  }
  if (error instanceof InvalidOrderTransitionError) {
    return {
      kind: 'conflict',
      code: 'INVALID_STATE_TRANSITION',
      message: error.message,
      details: { from: error.from, to: error.to },
    };
  }
  if (error instanceof ConflictError) {
    return { kind: 'conflict', code: 'CONFLICT', message: error.message };
  }
  return { kind: 'internal', code: 'INTERNAL_ERROR', message: 'An unexpected error occurred' };
}

